{
  "schemaVersion": "0.2",
  "slug": "progress",
  "name": "Progress",
  "status": "experimental",
  "purpose": "Displays the completion progress of a task.",
  "scenarios": [
    "Show file upload progress",
    "Show form completion",
    "Show loading progress"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": true,
      "description": "Current value."
    },
    "max": {
      "type": "number",
      "required": false,
      "description": "Maximum value.",
      "default": 100
    },
    "size": {
      "type": "enum",
      "required": false,
      "description": "Thickness.",
      "values": [
        "sm",
        "md"
      ],
      "default": "md"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "size",
      "values": [
        "sm",
        "md"
      ],
      "default": "md",
      "description": "Thickness."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Progress rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "form"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for indeterminate loading without a label.",
    "Do not set value above max."
  ],
  "a11y": {
    "role": "progressbar",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Value and max provide the accessible state.",
    "wcag": [
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Full width bar.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Native progress bar inherits direction; fill grows from inline-start.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "progress",
    "states": [
      "default"
    ],
    "intents": [
      "show-progress"
    ]
  }
}

import './styles.css'

export interface ProgressProps {
  value: number
  max?: number
  size?: 'sm' | 'md'
  className?: string
}

export function Progress({ value, max = 100, size = 'md', className }: ProgressProps) {
  const classes = ['cu-progress', 'cu-progress--' + size, className].filter(Boolean).join(' ')
  return (
    <progress
      className={classes}
      data-ai-role="progress" data-ai-state="default" data-ai-intent="show-progress"
      max={max}
      value={value}
    >
      {value}%
    </progress>
  )
}

.cu-progress {
  inline-size: 100%;
  block-size: 0.5rem;
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-border-default);
  color: var(--cu-color-palette-brand);
}

.cu-progress--sm {
  block-size: 0.25rem;
}

.cu-progress::-webkit-progress-bar {
  background: var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
}

.cu-progress::-webkit-progress-value {
  background: var(--cu-color-palette-brand);
  border-radius: var(--cu-radius-sm);
}

.cu-progress::-moz-progress-bar {
  background: var(--cu-color-palette-brand);
  border-radius: var(--cu-radius-sm);
}
